<template>
<div class="road-page"><Sidebar/><main class="road-main">
  <header class="road-top"><label>⌕ <input v-model="search" placeholder="Araç, plaka, model, talep no..." /></label><router-link to="/profile" class="road-account"><span class="road-avatar">{{initials}}</span><span><strong>{{customerName}}</strong><small>Filo Yöneticisi</small></span></router-link></header>
  <div v-if="loadError" class="road-alert" role="alert">{{loadError}} <button @click="load">Tekrar Dene</button></div><div v-if="notice" class="road-alert" role="status">{{notice}}</div><div class="road-content" :aria-busy="loading">
    <header class="heading"><div><h1>♧ Yol Yardım</h1><p>Araçlarınızın yol yardım taleplerini görüntüleyin, takip edin ve hızlıca çözüm sağlayın.</p></div><button class="primary" @click="openCreate">＋ Yol Yardım Talebi</button></header>
    <section class="metrics">
        <article><i>🚙</i><small>Toplam Talep</small><b>{{summary.total ?? 0}}</b></article><article class="red"><i>!</i><small>Devam Eden</small><b>{{summary.active ?? 0}}</b></article><article class="green"><i>✓</i><small>Tamamlanan</small><b>{{summary.resolved ?? 0}}</b></article><article><i>◷</i><small>Ortalama Yanıt Süresi</small><b>{{summary.average_response_minutes == null ? '—' : summary.average_response_minutes+' dk'}}</b></article><article class="last-week" :class="{ chosen: lastSevenDays }"><button @click="lastSevenDays=!lastSevenDays" :aria-pressed="lastSevenDays"><i>▣</i><small>Son 7 Gün</small><b>{{overview.last_seven_days_count || 0}}</b></button></article>
    </section>
    <div class="columns">
      <section class="list-col">
        <button class="mobile-filter-toggle" :aria-expanded="filtersExpanded" aria-controls="page-filters" @click="filtersExpanded=!filtersExpanded">{{filtersExpanded ? 'Filtreleri Gizle' : 'Filtreleri Aç'}} <span>⌄</span></button><div id="page-filters" class="filters" :class="{'mobile-expanded':filtersExpanded}"><label class="find">⌕ <input v-model="search" placeholder="Plaka, marka, model, talep no ara..." /></label><label><small>Araç Grubu</small><select v-model="groupFilter"><option value="all">Tümü</option><option v-for="g in groups" :key="g">{{g}}</option></select></label><label><small>Durum</small><select v-model="statusFilter"><option value="all">Tümü</option><option v-for="s in statuses" :key="s">{{s}}</option></select></label><label><small>Başlangıç Tarihi</small><input v-model="fromDate" type="date"/></label><label><small>Bitiş Tarihi</small><input v-model="toDate" type="date" :min="fromDate"/></label><button @click="page=1">⚲ Filtrele</button></div>
        <nav class="tabs"><button v-for="t in tabs" :key="t.key" :class="{active:activeTab===t.key}" @click="activeTab=t.key">{{t.label}} <b>{{summary.tabs?.[t.key] || 0}}</b></button></nav>
        <section class="panel"><header><b>♧ Yol Yardım Talepleri</b><button class="export" @click="exportCsv">↓ Dışa Aktar</button></header><div class="scroll"><table><thead><tr><th>Talep No</th><th>Tarih / Saat</th><th>Araç / Plaka</th><th>Konum</th><th>Arıza Nedeni</th><th>Durum</th><th>Gidişat</th><th></th></tr></thead><tbody>
          <tr v-if="loading && !cases.length"><td colspan="8" class="empty">Talepler yükleniyor…</td></tr><tr v-for="c in paginated" :key="c.id" :class="{selected:selected?.id===c.id}" @click="selectCase(c)"><td data-label="Talep" class="case-no"><button class="case-link" @click.stop="revealCase(c)">{{c.case_no}}</button></td><td data-label="Tarih">{{dateTime(c.created_at)}}</td><td data-label="Araç"><div class="vehicle-row"><img v-if="c.vehicle_photo" :src="c.vehicle_photo" alt="" /><span v-else class="vehicle-placeholder" aria-hidden="true">▱</span><span>{{c.vehicle_brand}} {{c.vehicle_model}}<b>{{c.plate}}</b></span></div></td><td data-label="Konum" class="loc">{{c.location||'Konum paylaşılmadı'}}</td><td data-label="Arıza">{{c.incident}}</td><td data-label="Durum"><span class="status" :class="statusClass(c.status)">{{c.status}}</span></td><td data-label="Gidişat"><small>%{{c.progress}}</small><div class="bar"><i :style="{width:c.progress+'%'}"></i></div></td><td data-label="İşlem"><button class="dots" :aria-label="c.case_no + ' detaylarını aç'" @click.stop="revealCase(c)"><span class="desktop-action-label">•••</span><span class="mobile-action-label">Detayları Gör</span></button></td></tr>
          <tr v-if="!loading && !paginated.length"><td colspan="8" class="empty">Yol yardım talebi bulunamadı.<button @click="openCreate">＋ Yeni Talep Oluştur</button></td></tr>
        </tbody></table></div><footer>Toplam {{filtered.length}} talep, {{start}}–{{end}} görüntüleniyor <span><button :disabled="page<=1" @click="page--">‹</button> {{page}} / {{pages}} <button :disabled="page>=pages" @click="page++">›</button></span></footer></section>
      </section>
      <aside class="details-col">
        <section class="panel detail"><header><b>♧ Talep Detayı</b><span v-if="selected" class="status" :class="statusClass(selected.status)">{{selected.status}}</span></header>
          <template v-if="selected"><div class="vehicle-info"><div class="car-img"><img v-if="selected.vehicle_photo" :src="selected.vehicle_photo" :alt="selected.vehicle_brand + ' ' + selected.vehicle_model" /><span v-else>▱</span></div><b>{{selected.vehicle_brand}} {{selected.vehicle_model}}</b><strong>{{selected.plate}}</strong><dl><dt>Marka / Model</dt><dd>{{selected.vehicle_brand}} / {{selected.vehicle_model}}</dd><dt>Şasi No</dt><dd>{{selected.chassis_no||'—'}}</dd><dt>Motor No</dt><dd>{{selected.engine_no||'—'}}</dd><dt>Renk</dt><dd>{{selected.color||'—'}}</dd><dt>Yıl</dt><dd>{{selected.vehicle_year||'—'}}</dd><dt>Kira Başlangıç</dt><dd>{{date(selected.contract_start_date)}}</dd><dt>Kira Bitiş</dt><dd>{{date(selected.contract_end_date)}}</dd></dl></div>
            <div v-if="mapSrc" class="map"><iframe :src="mapSrc" title="Talep konumu" loading="lazy"></iframe><span v-if="selected.eta_minutes != null || selected.distance_km != null" class="team-map-chip"><strong>{{selected.team_name || 'Yol Yardım Ekibi'}}</strong><small>{{selected.eta_minutes == null ? '—' : selected.eta_minutes+' dk'}} · {{selected.distance_km == null ? '—' : selected.distance_km+' km'}}</small></span><a :href="mapLink" target="_blank" rel="noreferrer">Haritada Aç ↗</a></div><div v-else class="map-empty">⌖ <b>Konum bilgisi paylaşılmadı</b></div>
            <div class="request-info"><button class="location-share" :disabled="sharingLocation" @click="shareLocation">{{sharingLocation ? 'Konum kaydediliyor…' : '⌖ Güncel Konumumu Paylaş'}}</button><h3>Talep Bilgileri</h3><dl><dt>Talep No</dt><dd>{{selected.case_no}}</dd><dt>Tarih / Saat</dt><dd>{{dateTime(selected.created_at)}}</dd><dt>Arıza Nedeni</dt><dd>{{selected.incident}}</dd><dt>Konum</dt><dd>{{selected.location||'—'}}</dd><dt>Açıklama</dt><dd>{{selected.description||'—'}}</dd><dt>Yardım Ekibi</dt><dd>{{selected.team_name||'Atama bekleniyor'}}</dd><dt>Tahmini Varış</dt><dd>{{selected.eta_minutes==null?'—':selected.eta_minutes+' dk'}}</dd></dl><div class="actions"><button class="primary" @click="openMap">⌖ Konumda Aç</button><a v-if="selected.team_phone" :href="'tel:'+selected.team_phone">İletişime Geç</a><button v-else @click="supportContact">İletişime Geç</button></div></div>
          </template><p v-else class="empty-note">Detayları görmek için listeden talep seçin.</p>
        </section>
        <section class="panel timeline"><header><b>♧ Yol Yardım Süreci</b><button v-if="selected" @click="loadEvents(selected)">↻</button></header><p v-if="eventsLoading" class="empty-note">Süreç yükleniyor…</p><ol v-else-if="events.length"><li v-for="e in events" :key="e.id"><i>{{e.status==='Çözüldü'?'✓':'•'}}</i><div><b>{{e.title}}</b><small>{{dateTime(e.created_at)}}</small><p>{{e.description||''}}</p><small v-if="e.eta_minutes != null || e.distance_km != null">{{e.eta_minutes == null ? '—' : e.eta_minutes+' dk'}} · {{e.distance_km == null ? '—' : e.distance_km+' km'}}</small></div></li></ol><p v-else class="empty-note">Henüz süreç hareketi yok.</p></section>
      </aside>
    </div>
  </div>
</main>
<div v-if="modal" class="overlay" @click.self="modal=false"><section class="dialog"><header><div><small>FLEETRENT · YOL YARDIM</small><h2>Yeni Yol Yardım Talebi</h2></div><button @click="modal=false">×</button></header><form @submit.prevent="createCase"><div class="form-grid"><label>Araç<select v-model="form.vehicle_id" required><option value="" disabled>Araç seçin</option><option v-for="v in vehicles.filter(v=>v.is_active!==false)" :key="v.id" :value="v.id">{{v.plate}} · {{v.brand}} {{v.model}}</option></select></label><label>Arıza / İhtiyaç<select v-model="form.incident"><option>Kaza</option><option>Lastik patladı</option><option>Arıza</option><option>Akü bitti</option><option>Marş basmıyor</option><option>Yakıt bitti</option><option>Elektrik arızası</option><option>Kilit arızası</option><option>Diğer</option></select></label><label>Konum / Adres<input v-model.trim="form.location" placeholder="İl, ilçe, yol veya açık adres"/></label><label>Enlem (isteğe bağlı)<input v-model.number="form.latitude" type="number" step="any"/></label><label>Boylam (isteğe bağlı)<input v-model.number="form.longitude" type="number" step="any"/></label></div><label>Açıklama<textarea v-model.trim="form.description" rows="3" placeholder="Durumu ve ihtiyacınızı açıklayın"/></label><p v-if="error" class="error">{{error}}</p><footer><button type="button" class="cancel" @click="modal=false">Vazgeç</button><button class="primary" :disabled="saving">{{saving?'Gönderiliyor…':'Yardım Talebi Oluştur'}}</button></footer><small class="privacy">Konum yalnızca bu yol yardım talebi için saklanır.</small></form></section></div>
</div>
</template>

<script setup>
import { ref, reactive, computed, onMounted, onUnmounted, watch, nextTick } from 'vue'
import Sidebar from '../components/Sidebar.vue'
const filtersExpanded=ref(false)
const customerId=localStorage.getItem('fleetcar_customer_id') || localStorage.getItem('customer_id')
const customerName=localStorage.getItem('fleetcar_customer_name') || 'Filo Yöneticisi'
const initials=customerName.split(' ').slice(0,2).map(word=>word[0]).join('').toUpperCase()
const overview=ref({}), cases=ref([]), vehicles=ref([]), events=ref([]), selected=ref(null)
const search=ref(''), groupFilter=ref('all'), statusFilter=ref('all'), fromDate=ref(''), toDate=ref(''), activeTab=ref('all'), lastSevenDays=ref(false), page=ref(1)
const modal=ref(false), saving=ref(false), error=ref(''), loading=ref(false), loadError=ref(''), notice=ref(''), eventsLoading=ref(false), sharingLocation=ref(false)
const statuses=['Beklemede','Ekip Atandı','Yola Çıktı','Yolda','Ekip Varış Noktasında','Çözüldü','İptal Edildi']
const tabs=[{key:'all',label:'Tümü'},{key:'Beklemede',label:'Beklemede'},{key:'moving',label:'Yolda'},{key:'Çözüldü',label:'Çözüldü'},{key:'İptal Edildi',label:'İptal Edildi'}]
const form=reactive({vehicle_id:'',incident:'Kaza',location:'',latitude:null,longitude:null,description:''})
const groups=computed(()=>[...new Set(cases.value.map(c=>c.vehicle_group).filter(Boolean))].sort())
const summary=computed(()=>(lastSevenDays.value ? overview.value.last_seven_days : overview.value.summary) || {})
const filtered=computed(()=>cases.value.filter(c=>{
  const q=search.value.trim().toLocaleLowerCase('tr-TR'), text=[c.case_no,c.plate,c.vehicle_brand,c.vehicle_model,c.incident,c.location,c.description].join(' ').toLocaleLowerCase('tr-TR'), day=String(c.created_at||'').slice(0,10)
  return (!q||text.includes(q)) && (groupFilter.value==='all'||c.vehicle_group===groupFilter.value) && (statusFilter.value==='all'||c.status===statusFilter.value) && (!fromDate.value||day>=fromDate.value) && (!toDate.value||day<=toDate.value) && (!lastSevenDays.value||overview.value.recent_case_ids?.includes(c.id)) && tabMatches(activeTab.value,c.status)
}))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10))), paginated=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10))
const start=computed(()=>filtered.value.length?(page.value-1)*10+1:0), end=computed(()=>Math.min(page.value*10,filtered.value.length))
function tabMatches(tab,status){return tab==='all'||(tab==='moving'?['Ekip Atandı','Yola Çıktı','Yolda','Ekip Varış Noktasında'].includes(status):status===tab)}
const mapSrc=computed(()=>{const c=selected.value;if(c?.latitude==null||c?.longitude==null)return '';const lat=Number(c.latitude),lon=Number(c.longitude),padding=.02;return `https://www.openstreetmap.org/export/embed.html?bbox=${encodeURIComponent([lon-padding,lat-padding,lon+padding,lat+padding].join(','))}&layer=mapnik&marker=${lat},${lon}`})
const mapLink=computed(()=>selected.value?.latitude==null?null:`https://www.openstreetmap.org/?mlat=${selected.value.latitude}&mlon=${selected.value.longitude}#map=15/${selected.value.latitude}/${selected.value.longitude}`)
watch([search,groupFilter,statusFilter,fromDate,toDate,activeTab,lastSevenDays],()=>page.value=1)
watch(pages,count=>{if(page.value>count)page.value=count})
function statusClass(status){return ({Beklemede:'pending','Ekip Atandı':'assigned','Yola Çıktı':'moving',Yolda:'moving','Ekip Varış Noktasında':'moving',Çözüldü:'resolved','İptal Edildi':'cancelled'})[status]||'pending'}
function date(value){if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleDateString('tr-TR')}
function dateTime(value){if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString('tr-TR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
async function json(url, options){const response=await fetch(url,options);if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(typeof data.detail==='string'?data.detail:'İşlem tamamlanamadı. Lütfen tekrar deneyin.')}return response.json()}
let refreshTimer, eventSequence=0
async function load(background=false){if(loading.value)return; if(!customerId){loadError.value='Müşteri bilgisi bulunamadı. Lütfen yeniden giriş yapın.';return}loading.value=true;try{
  const suffix='?customer_id='+encodeURIComponent(customerId)
  const data=await json('/api/roadside-overview'+suffix)
  overview.value=data;cases.value=data.cases;loadError.value=''
  if(!background)vehicles.value=await json('/api/vehicles'+suffix)
  const current=cases.value.find(c=>c.id===selected.value?.id)||cases.value[0]||null
  if(current)await selectCase(current);else {selected.value=null;events.value=[]}
}catch(e){loadError.value=e.message}finally{loading.value=false}}
async function revealCase(c){await selectCase(c);if(window.matchMedia('(max-width:600px)').matches){await nextTick();document.querySelector('.details-col')?.scrollIntoView({behavior:'smooth',block:'start'})}}
async function selectCase(c){selected.value=c;await loadEvents(c)}
async function loadEvents(c){const sequence=++eventSequence;eventsLoading.value=true;try{const data=await json('/api/roadside-cases/'+c.id+'/events');if(sequence===eventSequence && selected.value?.id===c.id)events.value=data}catch(e){if(sequence===eventSequence){events.value=[];notice.value='Süreç geçmişi yüklenemedi. Yenile düğmesiyle tekrar deneyin.'}}finally{if(sequence===eventSequence)eventsLoading.value=false}}
function openCreate(){Object.assign(form,{vehicle_id:vehicles.value.find(v=>v.is_active!==false)?.id||'',incident:'Kaza',location:'',latitude:null,longitude:null,description:''});error.value='';modal.value=true}
async function createCase(){saving.value=true;error.value='';try{const data=await json('/api/roadside-cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form,latitude:form.latitude===''?null:form.latitude,longitude:form.longitude===''?null:form.longitude})});modal.value=false;await load();const item=cases.value.find(c=>c.id===data.id);if(item)await selectCase(item)}catch(e){error.value=e.message}finally{saving.value=false}}
function openMap(){if(mapLink.value)window.open(mapLink.value,'_blank','noopener,noreferrer');else notice.value='Bu talep için koordinat paylaşılmamış.'}
async function shareLocation(){if(!selected.value)return;if(!navigator.geolocation){notice.value='Tarayıcı konum paylaşımını desteklemiyor.';return}const caseId=selected.value.id;sharingLocation.value=true;navigator.geolocation.getCurrentPosition(async position=>{try{await json('/api/roadside-cases/'+caseId,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({latitude:position.coords.latitude,longitude:position.coords.longitude})});await load(true);notice.value='Konumunuz yol yardım ekibiyle paylaşıldı.'}catch(e){notice.value=e.message}finally{sharingLocation.value=false}},()=>{notice.value='Konum izni alınamadı. Tarayıcı izinlerini kontrol edin.';sharingLocation.value=false},{enableHighAccuracy:true,timeout:10000})}
function supportContact(){notice.value='Henüz ekip telefonu paylaşılmadı. Servis ekibi atandığında iletişim bilgisi burada görünecek.'}
function exportCsv(){const header=['Talep No','Tarih','Plaka','Araç','Konum','Arıza Nedeni','Durum','Gidişat'];const rows=filtered.value.map(c=>[c.case_no,c.created_at,c.plate,[c.vehicle_brand,c.vehicle_model].join(' '),c.location,c.incident,c.status,c.progress+'%']);const csv=[header,...rows].map(row=>row.map(value=>'"'+String(value??'').replaceAll('"','""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));a.download='fleetrent-yol-yardim.csv';a.click();URL.revokeObjectURL(a.href)}
onMounted(()=>{load();refreshTimer=setInterval(()=>{if(!document.hidden && !modal.value)load(true)},15000)})
onUnmounted(()=>{clearInterval(refreshTimer);eventSequence++})
</script>

<style scoped>
